using Microsoft.EntityFrameworkCore; using SimplexLawFirm.Data; using SimplexLawFirm.Models; using SimplexLawFirm.Services.Email; using SimplexLawFirm.Services.Notifications;
namespace SimplexLawFirm.Services;
public interface IDiscoveryDisclosureService { Task<DiscoveryBundle> CreateAsync(int caseId,int attorneyId,string opponent,string email,IEnumerable<int> documentIds,Dictionary<int,string> privileged,CancellationToken ct=default); Task DecideAsync(int itemId,int directorId,bool withhold,string reason,CancellationToken ct=default); Task<DiscoveryBundle> FinaliseAsync(int bundleId,int attorneyId,string exchangeUrl,CancellationToken ct=default); Task<DiscoveryBundle> MarkAccessedAsync(string token,CancellationToken ct=default); Task RecordOpposingBundleAsync(int bundleId,IEnumerable<(string FileName,string RelativePath,string ContentType,long SizeBytes)> files,CancellationToken ct=default); Task SetComplianceAsync(int bundleId,int attorneyId,bool compliant,string notes,CancellationToken ct=default); Task EscalateGapsAsync(int bundleId,int attorneyId,CancellationToken ct=default); }
public sealed class DiscoveryDisclosureService(ApplicationDbContext db, INotificationService notices, IEmailService email) : IDiscoveryDisclosureService {
 public async Task<DiscoveryBundle> CreateAsync(int caseId,int attorneyId,string opponent,string email,IEnumerable<int> ids,Dictionary<int,string> privileged,CancellationToken ct=default){var matter=await db.Cases.SingleOrDefaultAsync(x=>x.Id==caseId&&x.LawyerId==attorneyId&&x.Status==CaseStatus.Active,ct)??throw new UnauthorizedAccessException();var docs=await db.Documents.Where(x=>ids.Contains(x.Id)&&x.CaseId==caseId).ToListAsync(ct);if(!docs.Any()||docs.Count!=ids.Distinct().Count()||string.IsNullOrWhiteSpace(opponent)||!new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(email))throw new InvalidOperationException("Select matter documents and valid opposing-attorney details.");var b=new DiscoveryBundle{CaseId=caseId,AttorneyId=attorneyId,OpposingAttorneyName=opponent.Trim(),OpposingAttorneyEmail=email.Trim(),ExchangeToken=Guid.NewGuid().ToString("N"),ExchangeExpiresAtUtc=DateTime.UtcNow.AddDays(7)};foreach(var d in docs){var p=privileged.TryGetValue(d.Id,out var r);if(p&&string.IsNullOrWhiteSpace(r))throw new InvalidOperationException("Each proposed privileged withholding needs a reason.");b.Items.Add(new DiscoveryBundleItem{DocumentId=d.Id,ProposedPrivileged=p,PrivilegeReason=r,PrivilegeDecision=p?PrivilegeDecision.Pending:PrivilegeDecision.OverruledDisclose});}b.Status=b.Items.Any(x=>x.ProposedPrivileged)?DiscoveryBundleStatus.AwaitingPrivilegeReview:DiscoveryBundleStatus.ReadyForExchange;db.Add(b);await db.SaveChangesAsync(ct);if(b.Status==DiscoveryBundleStatus.AwaitingPrivilegeReview)foreach(var id in await db.Users.Where(x=>(x.Role==UserRole.Director||x.Role==UserRole.Admin)&&x.IsActive).Select(x=>x.Id).ToListAsync(ct))await notices.QueueAsync(id,"DiscoveryPrivilegeReview","Discovery privilege review required",$"{matter.CaseNumber} has proposed withheld documents.",$"/DiscoveryDisclosure/Details/{b.Id}",$"discovery-review-{b.Id}-{id}",ct);await db.SaveChangesAsync(ct);return b;}
 public async Task DecideAsync(int itemId,int directorId,bool withhold,string reason,CancellationToken ct=default){if(!await db.Users.AnyAsync(x=>x.Id==directorId&&(x.Role==UserRole.Director||x.Role==UserRole.Admin),ct))throw new UnauthorizedAccessException();var i=await db.DiscoveryBundleItems.Include(x=>x.DiscoveryBundle).SingleAsync(x=>x.Id==itemId&&x.PrivilegeDecision==PrivilegeDecision.Pending,ct);if(string.IsNullOrWhiteSpace(reason))throw new InvalidOperationException("Director reasoning is required.");i.PrivilegeDecision=withhold?PrivilegeDecision.ApprovedWithheld:PrivilegeDecision.OverruledDisclose;i.DirectorId=directorId;i.DirectorReason=reason.Trim();i.DecidedAtUtc=DateTime.UtcNow;if(!await db.DiscoveryBundleItems.AnyAsync(x=>x.DiscoveryBundleId==i.DiscoveryBundleId&&x.Id!=i.Id&&x.PrivilegeDecision==PrivilegeDecision.Pending,ct))i.DiscoveryBundle.Status=DiscoveryBundleStatus.ReadyForExchange;await db.SaveChangesAsync(ct);}
 public async Task<DiscoveryBundle> FinaliseAsync(int id,int attorneyId,string exchangeUrl,CancellationToken ct=default){var b=await db.DiscoveryBundles.Include(x=>x.Items).SingleAsync(x=>x.Id==id&&x.AttorneyId==attorneyId,ct);if(b.Status!=DiscoveryBundleStatus.ReadyForExchange)throw new InvalidOperationException("All privilege decisions must be completed before exchange.");if(string.IsNullOrWhiteSpace(exchangeUrl))throw new InvalidOperationException("A public exchange URL is required.");b.Status=DiscoveryBundleStatus.Exchanged;b.ExchangedAtUtc=DateTime.UtcNow;await email.QueueAsync(b.OpposingAttorneyEmail,$"Discovery disclosure exchange",$"<p>Hello {System.Net.WebUtility.HtmlEncode(b.OpposingAttorneyName)},</p><p>The disclosure bundle is available securely at <a href='{System.Net.WebUtility.HtmlEncode(exchangeUrl)}'>this exchange portal</a>. The link expires {b.ExchangeExpiresAtUtc:dd MMM yyyy}.</p>",$"Discovery disclosure exchange: {exchangeUrl}",$"discovery-exchange-{id}",ct);db.AuditEntries.Add(new(){ActorUserId=attorneyId,EntityType=nameof(DiscoveryBundle),EntityId=id.ToString(),Action="Discovery bundle exchanged with opposing attorney"});await db.SaveChangesAsync(ct);return b;}
 public async Task<DiscoveryBundle> MarkAccessedAsync(string token,CancellationToken ct=default){var b=await db.DiscoveryBundles.SingleOrDefaultAsync(x=>x.ExchangeToken==token&&x.Status==DiscoveryBundleStatus.Exchanged&&x.ExchangeExpiresAtUtc>DateTime.UtcNow,ct)??throw new InvalidOperationException("This exchange link is unavailable or expired.");if(b.AccessedAtUtc is null){b.AccessedAtUtc=DateTime.UtcNow;db.AuditEntries.Add(new(){EntityType=nameof(DiscoveryBundle),EntityId=b.Id.ToString(),Action="Opposing party accessed discovery bundle"});await db.SaveChangesAsync(ct);}return b;}
 public async Task RecordOpposingBundleAsync(int id,IEnumerable<(string FileName,string RelativePath,string ContentType,long SizeBytes)> files,CancellationToken ct=default){var b=await db.DiscoveryBundles.SingleAsync(x=>x.Id==id&&x.Status==DiscoveryBundleStatus.Exchanged&&x.ExchangeExpiresAtUtc>DateTime.UtcNow,ct);var received=files.ToList();if(received.Count==0)throw new InvalidOperationException("Attach at least one opposing disclosure document.");foreach(var f in received)db.OpposingDisclosureDocuments.Add(new(){DiscoveryBundleId=id,FileName=f.FileName,RelativePath=f.RelativePath,ContentType=f.ContentType,SizeBytes=f.SizeBytes});b.OpposingBundleReceivedAtUtc ??= DateTime.UtcNow;b.Status=DiscoveryBundleStatus.Received;db.AuditEntries.Add(new(){EntityType=nameof(DiscoveryBundle),EntityId=id.ToString(),Action=$"Opposing disclosure bundle received ({received.Count} document(s))"});await db.SaveChangesAsync(ct);}
 public async Task SetComplianceAsync(int id,int attorneyId,bool ok,string notes,CancellationToken ct=default){var b=await db.DiscoveryBundles.SingleAsync(x=>x.Id==id&&x.AttorneyId==attorneyId,ct);if(b.OpposingBundleReceivedAtUtc==null)throw new InvalidOperationException("Record receipt of the opposing bundle before checking compliance.");if(string.IsNullOrWhiteSpace(notes))throw new InvalidOperationException(ok?"Record the compliance review outcome.":"Identify the missing disclosure documents or gaps.");b.Status=ok?DiscoveryBundleStatus.Compliant:DiscoveryBundleStatus.GapsIdentified;b.ComplianceNotes=notes.Trim();db.AuditEntries.Add(new(){ActorUserId=attorneyId,EntityType=nameof(DiscoveryBundle),EntityId=id.ToString(),Action=ok?"Opposing disclosure marked compliant":"Opposing disclosure gaps recorded"});await db.SaveChangesAsync(ct);}
 public async Task EscalateGapsAsync(int id,int attorneyId,CancellationToken ct=default){var b=await db.DiscoveryBundles.SingleAsync(x=>x.Id==id&&x.AttorneyId==attorneyId,ct);if(b.Status!=DiscoveryBundleStatus.GapsIdentified||string.IsNullOrWhiteSpace(b.ComplianceNotes))throw new InvalidOperationException("Record disclosure gaps before sending a formal follow-up.");await email.QueueAsync(b.OpposingAttorneyEmail,"Formal request for missing disclosure",$"<p>Hello {System.Net.WebUtility.HtmlEncode(b.OpposingAttorneyName)},</p><p>Please provide the following missing disclosure: {System.Net.WebUtility.HtmlEncode(b.ComplianceNotes)}.</p>",$"Formal request for missing disclosure: {b.ComplianceNotes}",$"discovery-gaps-{id}-{b.ComplianceNotes.GetHashCode()}",ct);db.AuditEntries.Add(new(){ActorUserId=attorneyId,EntityType=nameof(DiscoveryBundle),EntityId=id.ToString(),Action="Formal request for missing disclosure sent"});await db.SaveChangesAsync(ct);}
}
